import type { ButtonHTMLAttributes } from 'react';
import './toggle-icon-morph.css';

export interface ToggleIconMorphProps extends Omit<
  ButtonHTMLAttributes<HTMLButtonElement>,
  'onChange'
> {
  /** Current state: false shows a plus, true shows a close mark. */
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** Stays the same in both states; the state is announced separately. */
  label: string;
  /**
   * "expanded" for a button that shows and hides something (pass
   * `aria-controls` too); "pressed" for an on/off toggle.
   */
  mode?: 'expanded' | 'pressed';
}

/** A fixed-size button whose plus turns into a close mark. */
export function ToggleIconMorph({
  open,
  onOpenChange,
  label,
  mode = 'expanded',
  className = '',
  ...rest
}: ToggleIconMorphProps) {
  const state =
    mode === 'expanded' ? { 'aria-expanded': open } : { 'aria-pressed': open };
  return (
    <button
      type='button'
      className={`mg-morph ${className}`}
      aria-label={label}
      data-open={open}
      onClick={() => onOpenChange(!open)}
      {...state}
      {...rest}
    >
      <span className='mg-morph__bar' aria-hidden='true' />
      <span className='mg-morph__bar mg-morph__bar--v' aria-hidden='true' />
    </button>
  );
}

.mg-morph {
  position: relative;
  display: inline-grid;
  place-items: center;
  flex: none;
  width: 48px;
  height: 48px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: var(--mg-accent, #0047ff);
  color: #fff;
  cursor: pointer;
  transition: background-color 250ms ease;
}

.mg-morph[data-open='true'] {
  background: var(--mg-raised, #262626);
}

.mg-morph:focus-visible {
  outline: 3px solid var(--mg-accent-text, #648aff);
  outline-offset: 3px;
}

.mg-morph__bar {
  grid-area: 1 / 1;
  width: 20px;
  height: 2.5px;
  border-radius: 2px;
  background: currentColor;
  transition: transform 320ms cubic-bezier(0.3, 1.4, 0.5, 1);
}

.mg-morph__bar--v {
  transform: rotate(90deg);
}

/* A plus turned 45° is a cross; the bars also lengthen slightly. */
.mg-morph[data-open='true'] .mg-morph__bar {
  transform: rotate(45deg) scaleX(1.1);
}

.mg-morph[data-open='true'] .mg-morph__bar--v {
  transform: rotate(135deg) scaleX(1.1);
}

@media (prefers-reduced-motion: reduce) {
  .mg-morph,
  .mg-morph__bar {
    transition: none;
  }
}
